 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0]) if grid else 0
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 5 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 5 and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            top, bottom = min(y for y, x in cells), max(y for y, x in cells)
            left, right = min(x for y, x in cells), max(x for y, x in cells)
            # The objects are open-topped containers: color the cavity and its mouth.
            mouth = [x for x in range(left + 1, right) if grid[top][x] == 0]
            if not mouth or bottom <= top + 1:
                continue
            for y in range(top + 1, bottom):
                for x in range(left + 1, right):
                    if grid[y][x] == 0:
                        out[y][x] = 2
            for x in mouth:
                out[top][x] = 2
                if top > 0:
                    for xx in range(0, x + 1):
                        if grid[top - 1][xx] == 0:
                            out[top - 1][xx] = 2
    return out
